void can_dev_ena (Can_Dev_Id can_dev_id)
{
  CRITICAL ;

  #define U32(z1,z2) ((UInt32) z1 << z2)

  static const UInt32 can_ena [] =
    {
      U32 (1,13) ,  // CAN-0
      U32 (1,14) ,  // CAN-1
    } ;

  #undef  U32

  C_ENTER ;
    {
      PCONP |= can_ena [can_dev_id] ;
    }
  C_LEAVE ;
}


